import{_ as a,a as r}from"./chunks/supabase_sql_editor.CT34AdHe.js";import{_ as e,o,c as d,a0 as s}from"./chunks/framework.akKRIpjQ.js";const m=JSON.parse('{"title":"06 · 云同步（自建 Supabase · 多设备 + 照片备份）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/06-cloud-sync.md","filePath":"zh/guide/06-cloud-sync.md"}'),l={name:"zh/guide/06-cloud-sync.md"};function n(i,t,h,p,u,c){return o(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="_06-·-云同步-自建-supabase-·-多设备-照片备份" tabindex="-1">06 · 云同步（自建 Supabase · 多设备 + 照片备份） <a class="header-anchor" href="#_06-·-云同步-自建-supabase-·-多设备-照片备份" aria-label="Permalink to &quot;06 · 云同步（自建 Supabase · 多设备 + 照片备份）&quot;">​</a></h1><blockquote><p>App 出厂默认<strong>纯本地运行</strong>（不上传、不需要账号）。如需「多设备同步 + 照片备份」， 自建一个免费的 <a href="https://supabase.com" target="_blank" rel="noreferrer">Supabase</a> 项目（BYO 模式——每个用户自己的项目）， 把 URL + Anon Key 粘到登录页即可。<strong>完全可选</strong>。</p></blockquote><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li>去 <a href="https://supabase.com" target="_blank" rel="noreferrer">supabase.com</a> 注册账号 → Dashboard 点 <strong>「New project」</strong> 建一个免费档项目</li></ol><img src="'+a+'" alt="Supabase Dashboard — 创建新项目" style="max-width:720px;border-radius:12px;margin:12px 0;"><ol start="2"><li>项目就绪后 → 左侧菜单 → <strong>SQL Editor</strong> → <strong>+ New query</strong> → 粘贴 <code>schema.sql</code>（App 内有「<strong>复制 schema.sql</strong>」按钮一键复制）→ 点 <strong>Run</strong> 执行</li></ol><img src="'+r+'" alt="Supabase SQL Editor — 粘贴并执行 schema.sql" style="max-width:720px;border-radius:12px;margin:12px 0;"><ol start="3"><li><p>回 App 进「登录 / 注册（云同步）」页 → 选「<strong>未配置过</strong>」分支（首次） → 把 Supabase <code>Project URL</code> + <code>anon public key</code>（在 Project Settings → API 里）粘进去 → 保存</p></li><li><p>登录页三种方式任选一种：邮箱验证码 / GitHub OAuth / Google OAuth → 数据开始双向同步</p></li></ol><h2 id="登录页-3-种登录方式" tabindex="-1">登录页 3 种登录方式 <a class="header-anchor" href="#登录页-3-种登录方式" aria-label="Permalink to &quot;登录页 3 种登录方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>何时用</th></tr></thead><tbody><tr><td><strong>邮箱验证码</strong></td><td>零配置即用；适合首次 / 不想走 OAuth</td></tr><tr><td><strong>GitHub OAuth</strong></td><td>需要 Supabase 控制台启用 GitHub provider</td></tr><tr><td><strong>Google OAuth</strong></td><td>需要 Supabase 控制台启用 Google provider</td></tr></tbody></table><h2 id="登录页-3-个同步按钮" tabindex="-1">登录页 3 个同步按钮 <a class="header-anchor" href="#登录页-3-个同步按钮" aria-label="Permalink to &quot;登录页 3 个同步按钮&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>行为</th><th>风险</th></tr></thead><tbody><tr><td><strong>立即同步</strong></td><td>双向 LWW 合并；冲突建副本（<code>id#c&lt;毫秒&gt;</code>，两版本并存）</td><td>无</td></tr><tr><td><strong>从云端覆盖本地</strong> ⚠️</td><td>删本机全部 → 拉云端</td><td>本机未同步的改动丢失</td></tr><tr><td><strong>将本地覆盖到云端</strong> ⚠️</td><td>删云端你账号下全部 → 推本机</td><td>云端其他设备的改动被覆盖</td></tr></tbody></table><blockquote><p>后两个按钮会先弹 <strong>AlertDialog</strong> 列出「将删除 N 行 M 张图」+ 红底「<strong>确认覆盖</strong>」。</p></blockquote><h2 id="计费-配额" tabindex="-1">计费 / 配额 <a class="header-anchor" href="#计费-配额" aria-label="Permalink to &quot;计费 / 配额&quot;">​</a></h2><ul><li><strong>免费档</strong>：DB 500 MB / Storage 1 GB / 月活 50,000 —— 个人球拍 + 穿线 + 握把<strong>远用不完</strong></li><li>数据全部存在<strong>你自己</strong>的 Supabase 项目；AceCrush 团队看不到，开发者也看不到</li><li>想停用：App 内右上角「更换 Supabase 项目」图标 → 二次确认 → 清空当前会话</li></ul><h2 id="排错速查" tabindex="-1">排错速查 <a class="header-anchor" href="#排错速查" aria-label="Permalink to &quot;排错速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因 / 处理</th></tr></thead><tbody><tr><td>探测显示「✗ 表不存在」</td><td>没跑 schema.sql 或没成功 → 重跑步骤 2</td></tr><tr><td>探测显示「✗ Anon Key 无效」</td><td>复制时漏字符；重新完整复制 Project Settings → API 里的 anon public</td></tr><tr><td>GitHub / Google 登录报错「该登录方式未启用」</td><td>自建 Supabase 默认未配这两个 provider；去控制台启用或改用邮箱</td></tr><tr><td>邮箱登录收到的是「点击链接」而非 6 位码</td><td>控制台关「Confirm email」；Email Templates 正文含 token 占位（模板里写成 <code>&amp;#123;&amp;#123; .Token &amp;#125;&amp;#125;</code>，Supabase 渲染时替换为真验证码）</td></tr><tr><td>照片下载不下来（行同步成功但 photoUp = 0）</td><td>用「<strong>从云端覆盖本地</strong>」一键强拉</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./00-introduction.html">00 · 项目介绍</a></li><li><a href="./07-settings.html">07 · 设置</a></li><li><a href="./10-faq.html">10 · 常见问题</a></li></ul>',19)])])}const _=e(l,[["render",n]]);export{m as __pageData,_ as default};
